/** A connection to a list of `Supply` values. */
export type SuppliesConnection = {
  __typename?: 'SuppliesConnection';
  /** Aggregates across the matching connection (ignoring before/after/first/last/offset) */
  aggregates?: Maybe<SupplyAggregates>;
  /** A list of edges which contains the `Supply` and cursor to aid in pagination. */
  edges: Array<SuppliesEdge>;
  /** Grouped aggregates across the matching connection (ignoring before/after/first/last/offset) */
  groupedAggregates?: Maybe<Array<SupplyAggregates>>;
  /** A list of `Supply` objects. */
  nodes: Array<Maybe<Supply>>;
  /** Information to aid in pagination. */
  pageInfo: PageInfo;
  /** The count of *all* `Supply` you could get from the connection. */
  totalCount: Scalars['Int']['output'];
};


/** A connection to a list of `Supply` values. */
export type SuppliesConnectionGroupedAggregatesArgs = {
  groupBy: Array<SuppliesGroupBy>;
  having?: InputMaybe<SuppliesHavingInput>;
};

/** A `Supply` edge in the connection. */
export type SuppliesEdge = {
  __typename?: 'SuppliesEdge';
  /** A cursor for use in pagination. */
  cursor?: Maybe<Scalars['Cursor']['output']>;
  /** The `Supply` at the end of the edge. */
  node?: Maybe<Supply>;
};

/** Grouping methods for `Supply` for usage during aggregation. */
export enum SuppliesGroupBy {
  AMOUNT = 'AMOUNT',
  DENOM = 'DENOM',
  ID = 'ID'
}

export type SuppliesHavingAverageInput = {
  amount?: InputMaybe<HavingBigfloatFilter>;
};

export type SuppliesHavingDistinctCountInput = {
  amount?: InputMaybe<HavingBigfloatFilter>;
};

/** Conditions for `Supply` aggregates. */
export type SuppliesHavingInput = {
  AND?: InputMaybe<Array<SuppliesHavingInput>>;
  OR?: InputMaybe<Array<SuppliesHavingInput>>;
  average?: InputMaybe<SuppliesHavingAverageInput>;
  distinctCount?: InputMaybe<SuppliesHavingDistinctCountInput>;
  max?: InputMaybe<SuppliesHavingMaxInput>;
  min?: InputMaybe<SuppliesHavingMinInput>;
  stddevPopulation?: InputMaybe<SuppliesHavingStddevPopulationInput>;
  stddevSample?: InputMaybe<SuppliesHavingStddevSampleInput>;
  sum?: InputMaybe<SuppliesHavingSumInput>;
  variancePopulation?: InputMaybe<SuppliesHavingVariancePopulationInput>;
  varianceSample?: InputMaybe<SuppliesHavingVarianceSampleInput>;
};

export type SuppliesHavingMaxInput = {
  amount?: InputMaybe<HavingBigfloatFilter>;
};

export type SuppliesHavingMinInput = {
  amount?: InputMaybe<HavingBigfloatFilter>;
};

export type SuppliesHavingStddevPopulationInput = {
  amount?: InputMaybe<HavingBigfloatFilter>;
};

export type SuppliesHavingStddevSampleInput = {
  amount?: InputMaybe<HavingBigfloatFilter>;
};

export type SuppliesHavingSumInput = {
  amount?: InputMaybe<HavingBigfloatFilter>;
};

export type SuppliesHavingVariancePopulationInput = {
  amount?: InputMaybe<HavingBigfloatFilter>;
};

export type SuppliesHavingVarianceSampleInput = {
  amount?: InputMaybe<HavingBigfloatFilter>;
};

