export enum TxStatus {
  Error = 'Error',
  Success = 'Success'
}

/** A filter to be used against TxStatus fields. All fields are combined with a logical ‘and.’ */
export type TxStatusFilter = {
  /** Not equal to the specified value, treating null like an ordinary value. */
  distinctFrom?: InputMaybe<TxStatus>;
  /** Equal to the specified value. */
  equalTo?: InputMaybe<TxStatus>;
  /** Greater than the specified value. */
  greaterThan?: InputMaybe<TxStatus>;
  /** Greater than or equal to the specified value. */
  greaterThanOrEqualTo?: InputMaybe<TxStatus>;
  /** Included in the specified list. */
  in?: InputMaybe<Array<TxStatus>>;
  /** Is null (if `true` is specified) or is not null (if `false` is specified). */
  isNull?: InputMaybe<Scalars['Boolean']['input']>;
  /** Less than the specified value. */
  lessThan?: InputMaybe<TxStatus>;
  /** Less than or equal to the specified value. */
  lessThanOrEqualTo?: InputMaybe<TxStatus>;
  /** Equal to the specified value, treating null like an ordinary value. */
  notDistinctFrom?: InputMaybe<TxStatus>;
  /** Not equal to the specified value. */
  notEqualTo?: InputMaybe<TxStatus>;
  /** Not included in the specified list. */
  notIn?: InputMaybe<Array<TxStatus>>;
};

export type Validator = Node & {
  __typename?: 'Validator';
  commission: Scalars['JSON']['output'];
  createMsgId: Scalars['String']['output'];
  /** Reads a single `Account` that is related to this `Validator`. */
  delegator?: Maybe<Account>;
  delegatorId?: Maybe<Scalars['String']['output']>;
  delegatorShares?: Maybe<Scalars['String']['output']>;
  description: Scalars['JSON']['output'];
  ed25519Id: Scalars['String']['output'];
  id: Scalars['String']['output'];
  minSelfDelegation: Scalars['Int']['output'];
  /** A globally unique identifier. Can be used in various places throughout the system to identify this single value. */
  nodeId: Scalars['ID']['output'];
  /** Reads a single `Account` that is related to this `Validator`. */
  signer?: Maybe<Account>;
  signerId: Scalars['String']['output'];
  /** Reads a single `Account` that is related to this `Validator`. */
  signerPoktPrefix?: Maybe<Account>;
  signerPoktPrefixId: Scalars['String']['output'];
  stakeAmount: Scalars['BigFloat']['output'];
  stakeDenom: Scalars['String']['output'];
  stakeStatus: StakeStatus;
  /** Reads a single `Transaction` that is related to this `Validator`. */
  transaction?: Maybe<Transaction>;
  transactionId: Scalars['String']['output'];
};

